352	// cleanMemberAlias strips common suffixes (-proxy, -hosted, -local) for a friendlier display name.
353	func cleanMemberAlias(name string) string {
354		for _, suffix := range []string{"-proxy", "-hosted", "-local"} {
355			if strings.HasSuffix(name, suffix) {
356				return name[:len(name)-len(suffix)]
357			}
358		}
359		return name
